import {
    Table,
    BooleanColumn,
    IntegerColumn,
    ReferenceColumn,
    StringColumn,
    TableNameColumn,
    TranslatedFieldColumn,
} from '../../db'

export const sys_ui_module = Table({
    name: 'sys_ui_module',
    extends: 'sys_metadata',
    schema: {
        active: BooleanColumn({ default: true }),
        application: ReferenceColumn({ referenceTable: 'sys_ui_application' }),
        name: TranslatedFieldColumn({}),
        order: IntegerColumn({}),
        path: StringColumn({ maxLength: 3500 }),
        path_relative_to_root: BooleanColumn({ default: false }),
        roles: StringColumn({}),
        table: TableNameColumn({}),
        uncancelable: BooleanColumn({ default: false }),
        view_name: StringColumn({}),
    },
})
